import{z as s,x as A,o as E,c as p,q as t,j as i,D as e,d as o,s as l,S as n}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"线性表示假设","description":"","frontmatter":{"title":"线性表示假设","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/linear-representation-hypothesis.md","filePath":"llm/linear-representation-hypothesis.md","lastUpdated":1791413859000}'),B={name:"llm/linear-representation-hypothesis.md"};function h(d,a,m,_,c,u){const r=A("Mermaid");return E(),p("div",null,[a[2]||(a[2]=t('<h1 id="线性表示假设" tabindex="-1">线性表示假设 <a class="header-anchor" href="#线性表示假设" aria-label="Permalink to &quot;线性表示假设&quot;">​</a></h1><div class="epigraph"><p>非正式地说，线性表示假设认为高层概念在表示空间里沿某些方向线性编码。</p><footer>—— Park, Choe &amp; Veitch, The Linear Representation Hypothesis and the Geometry of Large Language Models, ICML 2024</footer></div><p>词向量算术（king − man + woman ≈ queen）早就暗示：语义关系可以是方向。语言模型的残差流把这一直觉从静态词表扩到上下文表示。线性表示假设（linear representation hypothesis, LRH）主张，许多高层概念——性别、时态、真实性、拒答——表现为空间中的方向，因而能被线性探针读出，也能被加法干预改写。Park、Choe 与 Veitch 在 ICML 2024 把这句口号写成反事实语言下的定义，并指出：没有选对的内积，余弦相似度和投影都可能没有语义。本篇写两种形式化、与探针/转向的对应、以及叠加对该假设的限制。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「线性」在文献里至少混用三种意思。一是探针可分：存在超平面切开正负例。二是干预可加：沿 \\(v\\) 移动会单调改变概念。三是类比算术：概念差向量可迁移。这三者在任意内积下并不自动等价。欧氏点积把高方差维度当成「更近」，而这些维度可能只是词频。于是出现一种尴尬：探针很准，转向却带动无关概念；或词表空间里的差向量，加到上下文残差上并不工作。</p><p>Park 等人要回答两个问题：线性表示究竟指什么；表示空间里该用哪种几何。他们用反事实：若只有概念 \\(W\\) 从 \\(w^-\\) 变到 \\(w^+\\)，表示应沿固定方向移动。对输出（词）空间与输入（上下文）空间分别定义，再证明它们对应探针与转向。</p><p><span class="marginnote">「反事实对」就是只差目标属性的最小对照组：man/woman 只差性别、walked/walks 只差时态。用这样的对去估计概念方向，差向量里才几乎不含别的因素；若拿「医生」和「护士」当反事实，差向量里混着性别、年代、收入一整堆纠缠属性，估出的「方向」没有因果含义。</span></p><h3 id="可分不等于可干预" tabindex="-1">可分不等于可干预 <a class="header-anchor" href="#可分不等于可干预" aria-label="Permalink to &quot;可分不等于可干预&quot;">​</a></h3><p>分类边界的法向量是读出方向；干预需要的是写入方向。在不正交的基下，读出与写入不是同一个向量。这解释了为何随便拿探针权重去加残差，效果不稳定。LRH 的有内容版本必须同时指定测量与干预，以及二者之间的对应。</p><p><span class="marginnote">Mikolov 的词类比是 LRH 的史前史，对象是静态嵌入。上下文残差里同一概念会随层变化，末层还要过解嵌。把 word2vec 的差向量直接当 LLM 转向向量，等于假设嵌入空间与残差空间共享几何——通常不成立。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>输出空间的线性表示：概念 \\(W\\) 对应词表表示上的方向 \\(\\bar{\\gamma}_W\\)，使得反事实词对的差与 \\(\\bar{\\gamma}_W\\) 对齐。这与线性探针相连——探针在读这个方向上的投影。输入空间的线性表示：概念对应上下文残差上的方向 \\(\\bar{\\lambda}_W\\)，加法干预沿 \\(\\bar{\\lambda}_W\\) 滑动概念，而不改变因果上可分的其他概念。这与转向相连。</p><p>关键构造是因果内积：在这套内积下，因果可分的概念被表示为正交向量。Park 等人证明，用这套内积可以通过 Riesz 对应把输出方向映成输入方向，于是词对差可以生成转向向量。估计上，他们用解嵌矩阵的协方差来近似该内积，并在 LLaMA-2 上验证：按因果内积构造的向量，比裸欧氏差更少泄漏到无关概念。</p><h3 id="反事实对的操作定义" tabindex="-1">反事实对的操作定义 <a class="header-anchor" href="#反事实对的操作定义" aria-label="Permalink to &quot;反事实对的操作定义&quot;">​</a></h3><p>实践中很少有完美反事实。近似是成对词或成对句子，尽量只在目标属性上不同。对质量决定估计出的方向。性别、时态这类有最小对的概念最适合检验 LRH；「有害性」几乎必然与话题纠缠，正交性只会近似成立。实验部分应报告：目标概念的可控制性，以及声称可分的对照概念是否保持不动。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>若下一层计算近似线性，方向编码可以在残差里传播：注意力与 MLP 的一阶效应是矩阵乘，投影可以保存。非线性（ReLU、注意力 softmax）会扭曲，但在工作点附近仍常有可用的一阶方向。这与叠加理论相容：Elhage 等人的玩具模型显示，稀疏概念可以以几乎正交的超完备方式塞进低维，线性读出仍然可能，干预却会碰到干扰。</p><p><span class="marginnote">数字实例：二维平面里严格互相垂直的方向最多 2 个，但 3 个方向两两夹 120°（余弦 \\(-0.5\\)）就「几乎不干扰」——叠加正是靠这种妥协，把远多于维数的概念塞进残差流。\\(d\\) 维空间里放 \\(n\\gg d\\) 个稀疏概念时，多数概念多数时刻不活跃，读出尚可，但沿其中任何一条方向做大幅干预都会蹭到别人。</span></p><h3 id="统一探针与转向" tabindex="-1">统一探针与转向 <a class="header-anchor" href="#统一探针与转向" aria-label="Permalink to &quot;统一探针与转向&quot;">​</a></h3><p>在因果内积下，测量表示与干预表示是对偶的。探针准确率高，意味着存在读出方向；用对偶映到干预方向，加法应改变该概念。这给工程一个处方：不要把 \\(W_{\\mathrm{probe}}\\) 直接当 \\(v_{\\mathrm{steer}}\\)，先按估计的内积做一次转换。LLaMA-2 实验表明这一转换是值得的——欧氏几何下「正交」的概念，在因果内积下才真正分开。</p>',20)),(E(),i(n,null,{default:e(()=>[l(r,{id:"mermaid-58",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%BA%BF%E6%80%A7%E6%8E%A2%E9%92%88%E6%9D%83%E9%87%8D%EF%BC%9A%E8%AF%BB%E5%87%BA%E6%96%B9%E5%90%91%22%5D%20--%3E%20NAIVE%5B%22%E7%9B%B4%E6%8E%A5%E5%BD%93%E8%BD%AC%E5%90%91%E5%90%91%E9%87%8F%E5%8A%A0%E8%BF%9B%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20NAIVE%20--%3E%20BAD%5B%22%E6%95%88%E6%9E%9C%E4%B8%8D%E7%A8%B3%EF%BC%8C%E8%B9%AD%E5%8A%A8%E6%97%A0%E5%85%B3%E6%A6%82%E5%BF%B5%22%5D%0A%20%20P%20--%3E%20CONV%5B%22%E5%85%88%E6%8C%89%E5%9B%A0%E6%9E%9C%E5%86%85%E7%A7%AF%E5%81%9A%20Riesz%20%E8%BD%AC%E6%8D%A2%22%5D%0A%20%20CONV%20--%3E%20V%5B%22%E5%B9%B2%E9%A2%84%E6%96%B9%E5%90%91%EF%BC%9A%E5%86%99%E5%85%A5%E6%96%B9%E5%90%91%22%5D%0A%20%20V%20--%3E%20GOOD%5B%22%E7%9B%AE%E6%A0%87%E6%A6%82%E5%BF%B5%E6%BB%91%E5%8A%A8%EF%BC%8C%E5%AF%B9%E7%85%A7%E6%A6%82%E5%BF%B5%E4%B8%8D%E5%8A%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">直觉类比：读出方向和写入方向像「麦克风最灵敏的朝向」和「喇叭最有效的朝向」——房间里的声学（内积）不对劲时，两者并不重合。先搞清房间的几何，再把「听」的方向换算成「喊」的方向，才不会喊偏。</span></p><p><span class="marginnote">内积选错时，余弦相似在解释性论文里没有字面意义。报告特征之间「相似」，应说明用的是欧氏、因果、还是白化后的点积。否则读者无法判断那条边是语义还是方差伪影。</span></p><p>LRH 不要求所有概念都线性。它要求：当我们声称某个概念可解释、可控制时，应能指出方向，并在选定几何下做测量与干预。失败案例（高度非线性的绑定、必须用多方向子空间才能表达的关系）应被当成假设的边界，而不是忽略。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>叠加、多义层、以及「概念」本身切得太随便，都会让单方向模型破产。有的属性更像子空间或凸锥，而不是一条线；强制压成 \\(v\\) 会在 \\(\\alpha\\) 大时崩。层选择仍然经验：中层常比嵌入层更符合 LRH，因为计算已经发生、解嵌尚未把几何拧到词表频率上。</p><p>把 LRH 当本体论（「模型真的用方向思考」）过强；当方法论（「先试线性读写，失败再上非线性工具」）则很有效。SAE 特征、归因图、转向向量，都在赌某种线性结构。赌赢时解释便宜；赌输时不要硬编故事。</p><p><span class="marginnote">因果可分是相对于干预集而言的。若你从未干预「语体」，就不能声称情感方向与语体正交。正交性声明必须带干预清单，否则只是训练集上的不相关。</span></p>',7)),(E(),i(n,null,{default:e(()=>[l(r,{id:"mermaid-80",class:"mermaid",graph:"flowchart%20TD%0A%20%20CF%5B%22%E5%8F%8D%E4%BA%8B%E5%AE%9E%E6%A6%82%E5%BF%B5%E5%AF%B9%22%5D%20--%3E%20Out%5B%22%E8%BE%93%E5%87%BA%E7%A9%BA%E9%97%B4%E6%96%B9%E5%90%91%20%CE%B3%22%5D%0A%20%20CF%20--%3E%20In%5B%22%E8%BE%93%E5%85%A5%E7%A9%BA%E9%97%B4%E6%96%B9%E5%90%91%20%CE%BB%22%5D%0A%20%20Out%20--%3E%20Probe%5B%22%E7%BA%BF%E6%80%A7%E6%8E%A2%E9%92%88%20%2F%20%E6%B5%8B%E9%87%8F%22%5D%0A%20%20In%20--%3E%20Steer%5B%22%E5%8A%A0%E6%B3%95%E8%BD%AC%E5%90%91%20%2F%20%E5%B9%B2%E9%A2%84%22%5D%0A%20%20IP%5B%22%E5%9B%A0%E6%9E%9C%E5%86%85%E7%A7%AF%22%5D%20--%3E%20Out%0A%20%20IP%20--%3E%20In%0A%20%20Out%20--%3E%7C%22Riesz%20%E5%AF%B9%E5%BA%94%22%7C%20In%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>线性表示假设认为高层概念沿方向编码；正式化需要反事实，而不是一句「能被线性分类」。</li><li>测量方向与干预方向在一般内积下不是同一个向量；因果内积把二者统一。</li><li>探针对应输出空间的线性可读，转向对应输入空间的线性可写。</li><li>欧氏余弦可能被词频主导；几何选择是实质问题，不是绘图口味。</li><li>叠加与非线性规定了假设的边界：先试方向，失败则承认需要子空间或电路。</li><li>出处：Park, Choe &amp; Veitch, ICML 2024（arXiv:2311.03658）；词类比见 Mikolov et al.；叠加见 Elhage et al., <em>Toy Models of Superposition</em>, 2022。</li></ul>',2))])}const b=s(B,[["render",h]]);export{D as __pageData,b as default};
